{{!-- Styling parameters: class, labelClass, inputClass, descriptionClass --}}
{{#with this as |ghostcnStyles|}}
<div class="ghcn-ui-field{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" data-variant="{{#match variant "filled"}}filled{{else}}default{{/match}}" data-size="{{#match size "sm"}}sm{{else}}{{#match size "lg"}}lg{{else}}default{{/match}}{{/match}}">
  <label class="ghcn-ui-field__label"><span class="ghcn-ui-field__label-text{{#if ghostcnStyles.labelClass}} {{ghostcnStyles.labelClass}}{{/if}}">{{#if label}}{{label}}{{else}}Input{{/if}}{{#if required}} (required){{/if}}</span>
    <input class="ghcn-ui-field__input{{#if ghostcnStyles.inputClass}} {{ghostcnStyles.inputClass}}{{/if}}" type="{{#match type "email"}}email{{else}}{{#match type "search"}}search{{else}}{{#match type "url"}}url{{else}}{{#match type "number"}}number{{else}}{{#match type "password"}}password{{else}}text{{/match}}{{/match}}{{/match}}{{/match}}{{/match}}" {{#if name}}name="{{name}}"{{/if}} value="{{value}}" placeholder="{{placeholder}}" {{#if required}}required{{/if}} {{#if disabled}}disabled{{/if}} {{#if invalid}}aria-invalid="true"{{/if}} {{#if hintId}}aria-describedby="{{hintId}}"{{/if}} />
  </label>
  {{#if hint}}<p class="ghcn-ui-field__hint{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}" {{#if hintId}}id="{{hintId}}"{{/if}}>{{hint}}</p>{{/if}}
</div>
{{/with}}

.ghcn-ui-field { box-sizing: border-box; font-family: inherit; font-size: var(--ghcn-text-body, 16px); line-height: 1.5; color: var(--foreground); }
.ghcn-ui-field, .ghcn-ui-field * { box-sizing: border-box; }
.ghcn-ui-field:where([data-size="sm"]) { font-size: 14px; }
.ghcn-ui-field:where([data-size="lg"]) { font-size: 18px; }
.ghcn-ui-field:focus-visible, :where(.ghcn-ui-field) :focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: 2px; }
.ghcn-ui-field { width: 100%; }
.ghcn-ui-field__label { display: grid; gap: .375em; font-weight: 500; }
.ghcn-ui-field__input { min-height: var(--ghcn-control-height, 40px); padding: var(--ghcn-control-padding, 8px 14px); border-radius: var(--ghcn-control-radius, var(--radius, 8px)); font-size: var(--ghcn-text-small, 14px); line-height: 1.25; width: 100%; min-width: 0; border: 1px solid var(--input); background: var(--background); color: var(--foreground); font-family: inherit; }
:where(.ghcn-ui-field[data-size="sm"]) .ghcn-ui-field__input { min-height: 34px; padding: 5px 11px; font-size: 13px; }
:where(.ghcn-ui-field[data-size="lg"]) .ghcn-ui-field__input { min-height: 46px; padding: 10px 17px; font-size: 16px; }
:where(.ghcn-ui-field[data-variant="filled"]) .ghcn-ui-field__input { background: var(--muted); }
.ghcn-ui-field__input::placeholder { color: var(--muted-foreground); }
.ghcn-ui-field__input[aria-invalid="true"] { border-color: var(--destructive); }
.ghcn-ui-field__input:disabled { opacity: .5; cursor: not-allowed; }
.ghcn-ui-field__hint { color: var(--muted-foreground); font-size: .875em; margin: .5em 0 0; }
